const errors = { InvalidFile, BatchFailed, ImportCancelled, TransientBatchError }

/**
 * A CSV import: validate the file, then import it batch by batch.
 * The operator can pause, resume and cancel it while it runs.
 */
export const ImportJob = Roadbook.make<ImportJobDef>(ir, "ImportJob", errors)
